-- ==========================================================
-- بيانات التغذية الشاملة لقاعدة بيانات نظام إدارة الصيدلية (42+ دواء)
-- ==========================================================
USE pharmacy_db;

-- 1. إضافة المستخدمين مع الصلاحيات (مدير / مشرف / موظف)
-- كلمة المرور الافتراضية للجميع: password123 (أو 123456)
ON DUPLICATE KEY UPDATE username=VALUES(username), role=VALUES(role);

-- 2. إضافة الشركات الموردة المعتمدة
ON DUPLICATE KEY UPDATE name=VALUES(name);

-- 3. إضافة قائمة أدوية الصيدلية الشاملة (42+ دواء)
ON DUPLICATE KEY UPDATE 
    name=VALUES(name),
    generic_name=VALUES(generic_name),
    category=VALUES(category),
    price=VALUES(price), 
    stock_quantity=VALUES(stock_quantity), 
    expiry_date=VALUES(expiry_date),
    description=VALUES(description);

-- 4. إضافة طلبات وشحنات نموذجية
ON DUPLICATE KEY UPDATE total_amount=VALUES(total_amount), status=VALUES(status);

-- 5. إضافة تفاصيل عناصر الطلب
ON DUPLICATE KEY UPDATE quantity=VALUES(quantity), unit_price=VALUES(unit_price);

